56	  Future<void> _pickDob() async {
57	    final now = DateTime.now();
58	    // The picker simply cannot reach an under-18 date, so the client-side age
59	    // gate from spec 1.2 is structural rather than a validation message.
60	    final latestAllowed = DateTime(now.year - 18, now.month, now.day);
61	    final picked = await showDatePicker(
62	      context: context,
63	      initialDate: DateTime(now.year - 25, now.month, now.day),
64	      firstDate: DateTime(now.year - 100),
65	      lastDate: latestAllowed,
66	      helpText: 'Your date of birth',
67	    );
68	    if (picked != null) setState(() => _dob = picked);
69	  }
