71	  /// Coordinates are optional: the feed shows profiles it cannot measure rather
72	  /// than emptying itself, so a denied permission degrades instead of blocking.
73	  Future<void> _useCurrentLocation() async {
74	    fail();
75	    try {
76	      if (!await Geolocator.isLocationServiceEnabled()) {
77	        fail('Turn on location services to use distance filters.');
78	        return;
79	      }
80	      var permission = await Geolocator.checkPermission();
81	      if (permission == LocationPermission.denied) {
