167	/// ------------------------------------------------------- verification
168	
169	final verificationProvider =
170	    AsyncNotifierProvider<VerificationNotifier, VerificationStatus>(VerificationNotifier.new);
171	
172	class VerificationNotifier extends RemoteAsync<VerificationStatus> {
173	  @override
174	  Future<VerificationStatus> fetch(Api api) async {
